550	// ── DB enrichment ─────────────────────────────────────────────────────────────
551	
552	fn enrich_hits(hits: &mut Vec<SearchHit>) {
553	    let Ok(conn) = crate::db::connect() else { return };
554	    for hit in hits.iter_mut() {
555	        let Some(sid) = &hit.session_id else { continue };
556	        if let Ok((agent, updated_at)) = conn.query_row(
557	            "SELECT agent_name, updated_at FROM sessions WHERE session_id = ?1",
558	            [sid.as_str()],
559	            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
560	        ) {
561	            hit.agent      = agent;
562	            hit.updated_at = updated_at;
563	            hit.backed_up  = true;
564	        }
565	    }
566	}
567	
568	// ── Direct name search ────────────────────────────────────────────────────────
569	
570	fn search_sessions_by_name(query: &str) -> Vec<SearchHit> {
571	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
572	    if words.is_empty() { return vec![]; }
573	
574	    let Ok(conn) = crate::db::connect() else { return vec![]; };
575	    let Ok(mut stmt) = conn.prepare(
576	        "SELECT session_id, session_name, cwd FROM sessions WHERE session_name != ''"
577	    ) else { return vec![]; };
578	
579	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
580	        .ok()
581	        .into_iter()
582	        .flatten()
583	        .flatten()
584	        .filter_map(|(session_id, session_name, cwd): (String, String, String)| {
585	            let normalized = session_name.to_lowercase().replace(['-', '_'], " ");
586	            if words.iter().all(|w| normalized.contains(w.as_str())) {
587	                Some(SearchHit {
588	                    kind: HitKind::Session,
589	                    title: session_name,
590	                    dir: short_path(&cwd),
591	                    excerpt_lines: vec![],
592	                    session_id: Some(session_id),
593	                    repo_dir: None,
594	                    start_ts: None, hit_ts: None, branch: String::new(),
595	                    agent: String::new(), backed_up: false, updated_at: String::new(),
596	                })
597	            } else {
598	                None
599	            }
600	        })
601	        .collect()
602	}
603	
604	fn search_repos_by_name(query: &str) -> Vec<SearchHit> {
605	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
606	    if words.is_empty() { return vec![]; }
607	
608	    let Ok(conn) = crate::db::connect() else { return vec![]; };
609	    let Ok(mut stmt) = conn.prepare(
610	        "SELECT name, directory FROM repositories WHERE name != ''"
611	    ) else { return vec![]; };
612	
613	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?)))
614	        .ok()
615	        .into_iter()
616	        .flatten()
617	        .flatten()
618	        .filter_map(|(name, directory): (String, String)| {
619	            let normalized = name.to_lowercase().replace(['-', '_'], " ");
620	            if words.iter().all(|w| normalized.contains(w.as_str())) {
621	                Some(SearchHit {
622	                    kind: HitKind::Repo,
623	                    title: name,
624	                    dir: short_path(&directory),
625	                    excerpt_lines: vec![],
626	                    session_id: None,
627	                    repo_dir: Some(directory),
628	                    start_ts: None, hit_ts: None, branch: String::new(),
629	                    agent: String::new(), backed_up: false, updated_at: String::new(),
630	                })
631	            } else {
632	                None
633	            }
634	        })
635	        .collect()
636	}
637	
638	// ── Helpers ───────────────────────────────────────────────────────────────────
639	
640	fn rel_time_hit(iso: &str) -> String {
641	    if iso.is_empty() { return String::new(); }
642	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return String::new(); };
643	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
644	    if secs < 604_800 {
645	        match secs {
646	            s if s < 60     => "just now".into(),
647	            s if s < 3_600  => format!("{} min ago", s / 60),
648	            s if s < 86_400 => format!("{} hr ago",  s / 3_600),
649	            s               => format!("{} day{} ago", s / 86_400, if s / 86_400 == 1 { "" } else { "s" }),
650	        }
651	    } else {
652	        dt.with_timezone(&chrono::Local).format("%m/%d/%y").to_string()
653	    }
654	}
655	
656	fn age_secs_hit(iso: &str) -> i64 {
657	    if iso.is_empty() { return i64::MAX; }
658	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return i64::MAX; };
659	    (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0)
660	}
661	
662	use super::agent_color;
663	
664	fn with_bg(s: &str, bg: &str) -> String {
665	    let reinsert = format!("\x1b[0m\x1b[{bg}m");
666	    format!("\x1b[{bg}m{}", s.replace("\x1b[0m", &reinsert))
667	}
668	
669	fn visible_len(s: &str) -> usize {
670	    let mut w = 0usize;
671	    let mut chars = s.chars().peekable();
672	    while let Some(c) = chars.next() {
673	        if c == '\x1b' {
674	            for nc in chars.by_ref() { if nc.is_ascii_alphabetic() { break; } }
675	        } else {
676	            w += 1;
677	        }
678	    }
679	    w
680	}
681	
682	fn short_path(path: &str) -> String {
683	    let home = std::env::var("HOME").unwrap_or_default();
684	    if !home.is_empty() && path.starts_with(&home) {
685	        format!("~{}", &path[home.len()..])
686	    } else {
687	        path.to_string()
688	    }
689	}
