pub fn run(json: bool) -> Result<()> {
    let conn = db::connect()?;

    let mut stmt = conn.prepare("SELECT directory, name FROM repositories")?;
    let repos: Vec<(String, String)> = stmt
        .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?
        .collect::<Result<_, _>>()?;

